from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_40 = Integer(40); _sage_const_10 = Integer(10); _sage_const_16 = Integer(16); _sage_const_4 = Integer(4); _sage_const_9 = Integer(9); _sage_const_160 = Integer(160); _sage_const_3 = Integer(3); _sage_const_1000 = Integer(1000); _sage_const_1p2 = RealNumber('1.2'); _sage_const_24 = Integer(24); _sage_const_15 = Integer(15); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_1p27 = RealNumber('1.27')
import sys
import time

def precompute_V():
    V = {_sage_const_1 }
    for s in range(_sage_const_40 ):
        fs = (_sage_const_10  * _sage_const_16 **s + _sage_const_16  * _sage_const_4 **s + _sage_const_10 ) // _sage_const_9 
        for i in range(_sage_const_160 ):
            val = fs * _sage_const_4 **i
            V.add(val)
    return sorted(list(V))

all_V = precompute_V()

# Primes pool
primes_pool = [p for p in prime_range(_sage_const_3 , _sage_const_1000 ) if p % _sage_const_4  == _sage_const_3 ]

# We want to find a counterexample N_0.
# Let's greedily choose residues for the first 15 primes to cover v up to N_max^2.
# Let's say N_max is 1.2 * 10^24 (the absolute maximum limit).
N_max = int(_sage_const_1p2  * _sage_const_10 **_sage_const_24 )
limit = N_max * N_max
V_target = [v for v in all_V if v < limit]
print(f"V_target size for 1.2 * 10^24: {len(V_target)}")

selected_primes = []
selected_residues = {}
uncovered = list(V_target)

# We will select primes until the product exceeds 1.1 * 10^24 or we reach 16 primes
num_primes = _sage_const_15 
for step in range(num_primes):
    best_p = None
    best_r = None
    best_cov = -_sage_const_1 
    
    for p in primes_pool:
        if p in selected_primes:
            continue
        cov_for_r = [_sage_const_0 ] * p
        for v in uncovered:
            v_mod = v % p
            if v_mod == _sage_const_0 :
                cov_for_r[_sage_const_0 ] += _sage_const_1 
            elif pow(v_mod, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1 :
                for r in range(_sage_const_1 , p):
                    if (r*r) % p == v_mod:
                        cov_for_r[r] += _sage_const_1 
                        cov_for_r[p-r] += _sage_const_1 
                        break
        max_cov = max(cov_for_r)
        best_r_for_p = cov_for_r.index(max_cov)
        if max_cov > best_cov:
            best_cov = max_cov
            best_p = p
            best_r = best_r_for_p
            
    if best_cov <= _sage_const_0 :
        break
        
    selected_primes.append(best_p)
    selected_residues[best_p] = best_r
    new_uncovered = []
    r2 = (best_r * best_r) % best_p
    for v in uncovered:
        if v % best_p != r2:
            new_uncovered.append(v)
    uncovered = new_uncovered
    print(f"Selected Prime {best_p}, Residue {best_r} (covers {best_cov} elements). Uncovered remaining: {len(uncovered)}")

moduli = [_sage_const_2 ] + selected_primes
residues = [_sage_const_1 ] + [selected_residues[p] for p in selected_primes]
from math import prod as math_prod
base_prod = math_prod(moduli)
N0 = int(crt(residues, moduli))

print(f"CRT base: N0 = {N0}")
print(f"prod = {base_prod} (digits: {len(str(base_prod))})")

if N0 >= _sage_const_1p27  * _sage_const_10 **_sage_const_24 :
    print("Warning: N0 is larger than the limit!")
